public static GUPPricingTree find(GUPPriceTreeName _name, boolean _forUpdate = false)
{
    GUPPricingTree gupPriceTree;

    if (_name)
    {
        if (_forUpdate)
        {
            gupPriceTree.selectForUpdate(_forUpdate);
        }

        select firstonly gupPriceTree
            where gupPriceTree.Name == _name;
    }

    return gupPriceTree;
}

public boolean validatePriceTree()
{
    EcoResValue currentValue = this.getAttributeValueOnPriceTree();
    if (!currentValue.RecId)
    {
        return false;
    }

    EcoResValue existedValue;
    GUPPricingTree gupPricingTree;

    while select Name from gupPricingTree
        where gupPricingTree.Status == GUPDisabledEnabled::Enabled
            && gupPricingTree.Name != this.Name
    {
        existedValue = gupPricingTree.getAttributeValueOnPriceTree();

        if (currentValue.RecId && existedValue.RecId && currentValue.compareTo(existedValue) == 0)
        {
            warning(strFmt("@GlobalUnifiedPricing:GUPPriceTree_DuplicateValue", gupPricingTree.Name));
            return false;
        }
    }

    return true;
}

private EcoResValue getAttributeValueOnPriceTree()
{
    EcoResValue ecoResValue;
    EcoResAttributeValue ecoResAttributeValue;
    GUPPriceTreeInstanceValue gupPriceTreeInstanceValue = GUPPriceTreeInstanceValue::findByPriceTree(this.Name, this.DataAreaId);

    select firstonly Value from ecoResAttributeValue
        where ecoResAttributeValue.InstanceValue == gupPriceTreeInstanceValue.RecId;
    if (ecoResAttributeValue.RecId)
    {
        ecoResValue = EcoResValue::find(ecoResAttributeValue.Value);
    }
    else
    {
        warning(strFmt("@GlobalUnifiedPricing:GUPPriceTree_MissingAttributeValue", this.Name));
    }

    return EcoResValue::getConcreteEcoResValueRecord(ecoResValue);
}

public static boolean shouldSkipFindPriceTree()
{
    return false;
}

public static GUPPriceTreeName findPriceTreeNameBySalesId(SalesId _salesId)
{
    GUPPriceTreeName priceTreeName;

    // Find price tree name when price tree is enabled.

    GUPPricingTree matchedPriceTree = GUPPricingTree::getPriceTreeBySalesId(_salesId);

    if (matchedPriceTree.RecId && !GUPPricingTree::shouldSkipFindPriceTree())
    {
        priceTreeName = matchedPriceTree.Name;
    }

    return priceTreeName;
}

public static GUPPriceTreeName findPriceTreeNameByPricingSimulator(ConfigName _name)
{
    GUPPriceTreeName priceTreeName;

    // Find price tree name when price tree is enabled.
    if (GUPParameters::find().EnablePriceTree && !GUPPricingTree::shouldSkipFindPriceTree())
    {
        EcoResValue ecoResValueOnSalesOrder = GUPPricingTree::getEcoResValueFromPriceSimulator(_name);

        GUPPricingTree matchedPriceTree = GUPPricingTree::getPriceTreeByEcoResValue(ecoResValueOnSalesOrder);

        if (matchedPriceTree.RecId)
        {
            priceTreeName = matchedPriceTree.Name;
        }
        else
        {
            error("@GlobalUnifiedPricing:CheckPriceTreeSetup");
        }
    }

    return priceTreeName;
}

internal static EcoResValue getEcoResValueFromSalesId(SalesId _salesId, boolean _showWarning = true)
{
    EcoResValue ecoResValue;
    EcoResAttributeValue ecoResAttributeValue;
    RetailSalesTableInstanceValue salesTableInstanceValue = RetailSalesTableInstanceValue::findBySalesTable(_salesId, curExt());

    // For now, only one attribute value is allowed for price tree.
    select firstonly Value from ecoResAttributeValue
        where ecoResAttributeValue.InstanceValue == salesTableInstanceValue.RecId;
    if (ecoResAttributeValue.RecId)
    {
        ecoResValue = EcoResValue::find(ecoResAttributeValue.Value);
    }
    else
    {
        if (_showWarning)
        {
            warning(strFmt("@GlobalUnifiedPricing:SalesOrderMissingAttribute", _salesId));
        }
    }

    return EcoResValue::getConcreteEcoResValueRecord(ecoResValue);
}

private static EcoResValue getEcoResValueFromPriceSimulator(ConfigName _name)
{
    EcoResValue ecoResValue;
    EcoResAttributeValue ecoResAttributeValue;
    GUPPricingSimulatorInstanceValue pricingSimulatorInstanceValue = GUPPricingSimulatorInstanceValue::findByPricingSimulator(_name, curExt());

    // For now, only one attribute value is allowed for price tree.
    select firstonly Value from ecoResAttributeValue
        where ecoResAttributeValue.InstanceValue == pricingSimulatorInstanceValue.RecId;
    if (ecoResAttributeValue.RecId)
    {
        ecoResValue = EcoResValue::find(ecoResAttributeValue.Value);
    }
    else
    {
        warning(strFmt("@GlobalUnifiedPricing:PricingSimulatorMissingAttribute", _name));
    }

    return EcoResValue::getConcreteEcoResValueRecord(ecoResValue);
}

private static GUPPricingTree getPriceTreeByEcoResValue(EcoResValue _ecoResValueOnSalesTable)
{
    GUPPricingTree gupPriceTree, matchedPriceTree;
    EcoResValue ecoResValueOnPriceTree;
    int cnt = 0;

    if (_ecoResValueOnSalesTable.RecId)
    {
        while select * from gupPriceTree
            where gupPriceTree.Status == GUPDisabledEnabled::Enabled
        {
            ecoResValueOnPriceTree = gupPriceTree.getAttributeValueOnPriceTree();
            if (ecoResValueOnPriceTree.RecId && ecoResValueOnPriceTree.compareTo(_ecoResValueOnSalesTable) == 0)
            {
                matchedPriceTree = GUPPricingTree::find(gupPriceTree.Name);
                cnt++;

                if (cnt > 1)
                {
                    error("@GlobalUnifiedPricing:SalesOrderValidation_MultiPriceTree");
                    matchedPriceTree = null;

                    return matchedPriceTree;
                }
            }
        }

        if (cnt == 0)
        {
            error("@GlobalUnifiedPricing:SalesOrderValidation_NoPriceTree");
            matchedPriceTree = null;
        }
    }

    return matchedPriceTree;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (!GUPParameters::find().EnablePriceTree)
    {
        ret = checkFailed("@GlobalUnifiedPricing:GUPPriceTree_ToggleIsNotEnabled");
    }

    return ret;
}

public static Set getComponentCodeNamesLinkedWithPriceTreeFromSalesId(SalesId _salesId)
{
    Set componentCodeNames = new Set(Types::String);

    GUPPricingTree matchedPriceTree = GUPPricingTree::getPriceTreeBySalesId(_salesId, false);

    if (matchedPriceTree.RecId)
    {
        GUPPriceComponentCodeSetup setup;
        while select PriceComponentCodeName from setup where setup.PricingTree == matchedPriceTree.RecId
        {
            componentCodeNames.add(setup.PriceComponentCodeName);
        }
    }

    return componentCodeNames;
}

public static GUPPricingTree getPriceTreeBySalesId(SalesId _salesId, boolean _showError = true)
{
    GUPPricingTree matchedPriceTree;

    if (GUPParameters::find().EnablePriceTree)
    {
        EcoResValue ecoResValueOnSalesOrder = GUPPricingTree::getEcoResValueFromSalesId(_salesId, false);

        matchedPriceTree = GUPPricingTree::getPriceTreeByEcoResValue(ecoResValueOnSalesOrder);

        if (!matchedPriceTree.RecId && _showError)
        {
            error("@GlobalUnifiedPricing:CheckPriceTreeSetup");
        }
    }

    return matchedPriceTree;
}
